// ---- settings you can tweak ----
const FIELD_PREFIX = 'Image ';   // -> Image 1, Image 2, ...
const START_INDEX  = 1;          // first field number
const MAX_IMAGES   = 30;         // cap how many to output
const DELETE_ORIGINAL_IMAGE_FIELDS = true; // remove images/Image Src/etc

// ---- helpers ----
const EXT_OK = /\.(jpe?g|png|webp|gif|avif|bmp|tiff)(\?.*)?$/i;
const BLOCK  = [/\/uploads\/anpc/i, /anpc-(sal|sol)\.png/i, /placeholder/i, /no-?image/i];

function collectAllImageUrls(input) {
  const out = [];
  const seen = new Set();

  const push = (u) => {
    if (!u) return;
    const s = String(u).trim().replace(/&amp;/g, '&');
    if (!/^https?:\/\//i.test(s)) return;
    if (!EXT_OK.test(s)) return;
    if (BLOCK.some((re) => re.test(s))) return;
    if (!seen.has(s)) { seen.add(s); out.push(s); }
  };

  const walk = (v) => {
    if (v == null) return;

    if (Array.isArray(v)) { v.forEach(walk); return; }

    if (typeof v === 'object') {
      // common keys
      if (v.src || v.url || v.href) push(v.src || v.url || v.href);
      Object.values(v).forEach(walk);
      return;
    }

    if (typeof v === 'string') {
      // try to parse JSON string of images if present
      try { const parsed = JSON.parse(v); walk(parsed); return; } catch {}
      // extract any image-like URLs from free text
      const rx = /(https?:\/\/[^\s"'<>]+?\.(?:jpe?g|png|webp|gif|avif|bmp|tiff)(?:\?[^\s"'<>]*)?)/ig;
      let m; while ((m = rx.exec(v))) push(m[1]);
      return;
    }
  };

  walk(input);
  return out;
}

// ---- main ----
return items.map(item => {
  const rec = { ...item.json };

  // look for images in the common places
  const sources = [
    rec['Image Src'], rec.images, rec.image, rec.photos, rec.photo, rec.gallery
  ];

  // gather, clean and cap
  let urls = [];
  sources.forEach(s => { urls = urls.concat(collectAllImageUrls(s)); });
  urls = [...new Set(urls)].slice(0, MAX_IMAGES);

  // write Image 1..N
  urls.forEach((u, i) => {
    rec[`${FIELD_PREFIX}${START_INDEX + i}`] = u;
  });


  // optionally remove original image fields so only split fields remain
  if (DELETE_ORIGINAL_IMAGE_FIELDS) {
    delete rec['Image Src'];
    delete rec.images;
    delete rec.image;
    delete rec.photos;
    delete rec.photo;
    delete rec.gallery;
  }

  return { json: rec };
});

// ===== Complete Fixed Version - Handles products without SKUs =====

// ---------- Helpers ----------
const S = v => (v == null ? '' : String(v).trim());
const U = v => S(v).toUpperCase();
const money = v => {
  if (v == null || v === '') return null;
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  const m = s.match(/-?\d+(\.\d+)?/);
  return m ? Number(m[0]).toFixed(2) : null;
};
const asListString = val => JSON.stringify([ S(val) ]);
const cleanList = raw => {
  const str = S(raw);
  return str.replace(/\s*\n+\s*/g, '\n').replace(/\s{2,}/g, ' ').replace(/,\s*,+/g, ', ');
};
const mapFuel = (raw) => {
  const v = (raw || '').toLowerCase().trim();
  const allowed = [
    'Benzină','Benzină (Mild-Hybrid)','Diesel','Diesel (Mild-Hybrid)',
    'Hybrid','Plug-in Hybrid','Electric','LPG'
  ];
  if (['benzina','benzină','gasoline','petrol'].includes(v)) return 'Benzină';
  if (['benzina (mild-hybrid)','benzină (mild-hybrid)','mhev benzina','mhev benzină','mild hybrid benzina'].includes(v)) return 'Benzină (Mild-Hybrid)';
  if (['diesel'].includes(v)) return 'Diesel';
  if (['diesel (mild-hybrid)','mhev diesel','mild hybrid diesel'].includes(v)) return 'Diesel (Mild-Hybrid)';
  if (['hybrid','full hybrid','hev'].includes(v)) return 'Hybrid';
  if (['phev','plug-in hybrid','plugin hybrid'].includes(v)) return 'Plug-in Hybrid';
  if (['electric','ev','bev'].includes(v)) return 'Electric';
  if (['lpg','gaz','gpl'].includes(v)) return 'LPG';
  return allowed.includes(raw) ? raw : 'Benzină';
};

// ---------- Process all input items (created products) ----------
const createdItems = $input.all();
const out = [];

console.log('IN items:', createdItems.length);

// Get all filtered items that contain the source data
const filteredItems = [];
try {
  // Try to get the Filter node output which contains all the source data
  filteredItems.push(...$('Filter').all());
  console.log('Got filtered items:', filteredItems.length);
} catch (e) {
  console.log('Could not get Filter node data:', e.message);
}

// Build maps for matching: by SKU, by handle, and by title
const skuToSourceMap = new Map();
const handleToSourceMap = new Map();
const titleToSourceMap = new Map();

for (const item of filteredItems) {
  const data = item.json || {};

  // Map by SKU if available
  const sku = S(data['Variant SKU'] || data.variant_sku || data.sku || '');
  if (sku) {
    skuToSourceMap.set(sku, data);
    console.log(`Mapped SKU "${sku}" to source data`);
  }

  // Map by handle
  const handle = S(data.Handle || data.handle || '');
  if (handle) {
    handleToSourceMap.set(handle, data);
    console.log(`Mapped handle "${handle}" to source data`);
  }

  // Map by title
  const title = S(data.Title || data.title || '');
  if (title) {
    titleToSourceMap.set(title, data);
    console.log(`Mapped title "${title}" to source data`);
  }
}

console.log(`Source maps built: ${skuToSourceMap.size} SKUs, ${handleToSourceMap.size} handles, ${titleToSourceMap.size} titles`);

for (let i = 0; i < createdItems.length; i++) {
  const created = createdItems[i].json || {};
  const product_id = created.id;
  const variant_id = created?.variants?.[0]?.id;

  if (!product_id || !variant_id) {
    console.log(`ERROR: Missing product_id or variant_id for item ${i}`);
    out.push({ json: { error: 'Missing product_id or variant_id', index: i, created } });
    continue;
  }

  // Get the SKU from the created product (might be null)
  const createdSku = S(created?.variants?.[0]?.sku || '');
  const createdHandle = S(created.handle || '');
  const createdTitle = S(created.title || '');

  // Try to find matching source data by multiple methods
  let row = {};
  let matchMethod = 'none';

  // 1. Try SKU match first (if SKU exists)
  if (createdSku && skuToSourceMap.has(createdSku)) {
    row = skuToSourceMap.get(createdSku);
    matchMethod = 'sku';
    console.log(`Found source data for product ${product_id} by SKU "${createdSku}"`);
  }
  // 2. Try handle match
  else if (createdHandle && handleToSourceMap.has(createdHandle)) {
    row = handleToSourceMap.get(createdHandle);
    matchMethod = 'handle';
    console.log(`Found source data for product ${product_id} by handle "${createdHandle}"`);
  }
  // 3. Try title match
  else if (createdTitle && titleToSourceMap.has(createdTitle)) {
    row = titleToSourceMap.get(createdTitle);
    matchMethod = 'title';
    console.log(`Found source data for product ${product_id} by title "${createdTitle}"`);
  }
  // 4. Try index-based fallback (if all else fails)
  else if (i < filteredItems.length) {
    row = filteredItems[i]?.json || {};
    matchMethod = 'index';
    console.log(`Using index-based match for product ${product_id} (fallback)`);
  }
  else {
    console.log(`WARNING: No source data found for product ${product_id}`);
    matchMethod = 'none';
  }

  // Get the variant SKU from source data or use what's in the created product
  const variant_sku = S(row['Variant SKU'] || row.variant_sku || row.sku || createdSku || '');
  const variant_price = money(row['Variant Price'] || row.variant_price);

  // Build meta_blueprint only if we have source data
  let bp = {};
  if (Object.keys(row).length > 0 && matchMethod !== 'none') {
    bp = {
      // Mirrors
      sku:            { type: 'single_line_text_field', value: variant_sku },
      price_gross:    { type: 'number_decimal',         value: money(row['Variant Price']) },
      pret_fara_tva:  { type: 'number_decimal',         value: money(row['Metafield: custom.pret_fara_tva [single_line_text_field]']) },
      currency:       { type: 'single_line_text_field', value: 'RON' },

      // Business attributes
      nr_dos_:        { type: 'single_line_text_field', value: S(row['Metafield: custom.nr_dos_ [single_line_text_field]']) },
      model:          { type: 'single_line_text_field', value: S(row['Metafield: custom.model [single_line_text_field]']) },
      marca:          { type: 'single_line_text_field', value: S(row['Metafield: custom.marca [single_line_text_field]']) },
      putere_kw:      { type: 'single_line_text_field', value: S(row['Metafield: custom.putere_kw [single_line_text_field]']) },
      putere_cp:      { type: 'single_line_text_field', value: S(row['Metafield: custom.putere_cp [single_line_text_field]']) },

      // transmisie + fuel will be overwritten below with correct types/values
      transmisie:     { type: 'single_line_text_field', value: S(row['Metafield: custom.transmisie [list.single_line_text_field]']) },
      tva:            { type: 'single_line_text_field', value: S(row['Metafield: custom.tva [single_line_text_field]']) },
      cilindree:      { type: 'single_line_text_field', value: S(row['Metafield: custom.cilindree [single_line_text_field]']) },
      cutie_viteze:   { type: 'single_line_text_field', value: S(row['Metafield: custom.cutie_viteze [single_line_text_field]']) },
      culoare:        { type: 'single_line_text_field', value: S(row['Metafield: custom.culoare [single_line_text_field]']) },
      kilometraj:     { type: 'single_line_text_field', value: S(row['Metafield: custom.km [single_line_text_field]']) },
      data_livrarii:  { type: 'single_line_text_field', value: S(row['Metafield: custom.data_livrarii [single_line_text_field]']) },
      body_type:      { type: 'single_line_text_field', value: S(row['Metafield: custom.body_type [single_line_text_field]']) },
      fuel:           { type: 'single_line_text_field', value: S(row['Metafield: custom.fuel [single_line_text_field]']) },
      dotari:         { type: 'multi_line_text_field',
                        value: Array.isArray(row['Metafield: custom.dotari [multi_line_text_field]'])
                          ? cleanList(row['Metafield: custom.dotari [multi_line_text_field]'].join(', '))
                          : cleanList(row['Metafield: custom.dotari [multi_line_text_field]'] || '') }
    };

    // === Enforce store definitions to avoid GraphQL userErrors ===
    // 1) transmisie is a list.single_line_text_field → JSON array string
    const rawTransmisie =
      row['Metafield: custom.transmisie [list.single_line_text_field]'] ||
      row.transmisie || bp.transmisie?.value;
    if (rawTransmisie) {
      bp.transmisie = {
        type: 'list.single_line_text_field',
        value: asListString(rawTransmisie)
      };
    }

    // 2) fuel must match allowed choices
    const rawFuel =
      row['Metafield: custom.fuel [single_line_text_field]'] ||
      row.fuel || bp.fuel?.value;
    if (rawFuel) {
      bp.fuel = {
        type: 'single_line_text_field',
        value: mapFuel(rawFuel)
      };
    }
  }

  // Only create metafields if we have data
  const metafields = Object.entries(bp)
    .filter(([, def]) => def && def.value != null && def.value !== '')
    .map(([key, def]) => ({
      ownerId: `gid://shopify/Product/${product_id}`,
      namespace: 'custom',
      key,
      type: def.type,
      value: String(def.value)
    }));

  // Only create variant update if we have SKU or price
  const variant_update = {};
  if (variant_sku || variant_price) {
    variant_update.variant = {
      id: variant_id,
      ...(variant_sku   ? { sku: variant_sku }   : {}),
      ...(variant_price ? { price: variant_price } : {})
    };
  }

  const graphql_body = metafields.length > 0 ? {
    query: `
      mutation metafieldsSet($metafields: [MetafieldsSetInput!]!) {
        metafieldsSet(metafields: $metafields) {
          metafields { key namespace value }
          userErrors { field message code }
        }
      }
    `.trim(),
    variables: { metafields }
  } : null;

  const graphql_body_passthrough = graphql_body;

  out.push({
    json: {
      product_id,
      variant_id,
      variant_update: Object.keys(variant_update).length > 0 ? variant_update : null,
      graphql_body,
      graphql_body_passthrough,
      source_sku: variant_sku,
      source_index: i,
      has_source_data: Object.keys(row).length > 0,
      match_method: matchMethod,
      created_title: createdTitle,
      created_handle: createdHandle
    }
  });
}

console.log('OUT items:', out.length);
console.log('Summary:', out.map(item => ({
  product: item.json.product_id,
  match: item.json.match_method,
  has_data: item.json.has_source_data,
  sku: item.json.source_sku || 'NO_SKU'
})));

return out;

