// Safer Filter: SKU comparison with normalization and duplicate detection

const gidNum = (gid) => String(gid || '').split('/').pop();

// Normalize SKU consistently on BOTH sides
const normalizeSKU = (raw) => {
  if (raw == null) return '';
  return String(raw)
    .normalize('NFKC')                // unify Unicode forms
    .replace(/[\u200B-\u200D\uFEFF]/g, '') // strip zero-widths
    .replace(/\s+/g, '')              // remove all whitespace
    .trim()
    .toUpperCase();                   // case-insensitive match
};

console.log("=== SAFER FILTER: NORMALIZED SKU COMPARISON ===");

// 1) Get Shopify data (input to this node)
const shopifyResults = $input.all().map(i => i.json);
console.log(`Shopify results received: ${shopifyResults.length}`);

// 2) Build normalized SKU index with variant IDs from Shopify GraphQL response
const skuIndex = new Map();          // key: skuKey → primary entry
const duplicateIndex = new Map();    // key: skuKey → array of ALL entries (for conflicts)
let totalExistingSKUs = 0;

for (const result of shopifyResults) {
  const productsData = result?.data?.products;
  if (!productsData) {
    console.log(`⚠️ No products data found in result`);
    continue;
  }

  const productEdges = productsData.edges ?? [];
  console.log(`Processing ${productEdges.length} products from Shopify GraphQL`);

  for (const productEdge of productEdges) {
    const product = productEdge.node;
    if (!product) continue;

    const productId = gidNum(product.id);
    const productTitle = product.title || 'Unknown';
    const vendor = product.vendor || '';
    const handle = product.handle || (productTitle.toLowerCase().replace(/\s+/g, '-') || '');

    const variantEdges = product.variants?.edges ?? [];
    console.log(`  Product "${productTitle}" (${vendor}) has ${variantEdges.length} variants`);

    for (const variantEdge of variantEdges) {
      const variant = variantEdge.node;
      if (!variant) continue;

      const variantId = gidNum(variant.id);
      const skuRaw = variant.sku ? String(variant.sku).trim() : '';
      const skuKey = normalizeSKU(skuRaw);
      const variantTitle = variant.title || '';

      console.log(`    Variant: ID="${variantId}", SKU_RAW="${skuRaw}", SKU_KEY="${skuKey}", Title="${variantTitle}"`);

      if (!skuKey || !variantId) {
        console.log(`    ⚠️  Skipped variant: missing ${!skuKey ? 'normalized SKU' : 'variant ID'}`);
        continue;
      }

      const entry = {
        product_id: productId,
        variant_id: variantId,
        handle,
        product_title: productTitle,
        variant_title: variantTitle,
        vendor,
        sku_raw: skuRaw,
        sku_key: skuKey
      };

      // Track all entries per key for conflict diagnostics
      const arr = duplicateIndex.get(skuKey) || [];
      arr.push(entry);
      duplicateIndex.set(skuKey, arr);

      // First one wins as the "primary" for compatibility with downstream logic
      if (!skuIndex.has(skuKey)) {
        skuIndex.set(skuKey, entry);
      } else {
        // We still keep first as primary, but we'll flag conflicts later
        console.log(`    ⚠️  Duplicate SKU detected for key "${skuKey}" (keeping first as primary)`);
      }

      totalExistingSKUs++;
    }
  }
}

console.log(`Built SKU index (normalized): ${totalExistingSKUs} variant SKUs from Shopify`);

// 3) Get incoming products from "Split images"
let incomingProducts = [];
try {
  const splitImagesItems = $('Split images').all();
  incomingProducts = splitImagesItems.map(item => item.json);
  console.log(`✅ Found ${incomingProducts.length} products from Split images`);
} catch (error) {
  console.log(`⚠️  Could not access Split images data: ${error.message}`);
  console.log(`Attempting fallback data retrieval...`);
  return [{
    json: {
      error: "Cannot access Split images data",
      shopify_skus_found: totalExistingSKUs,
      debug_info: "Filter node could not access incoming products for comparison"
    }
  }];
}

console.log(`\n=== PROCESSING ${incomingProducts.length} INCOMING PRODUCTS ===`);

const results = [];

// 4) Process each incoming product with normalized comparison
for (let i = 0; i < incomingProducts.length; i++) {
  const product = incomingProducts[i];

  // Pull SKU from possible fields, then normalize
  const skuRawIncoming = String(
    product['Variant SKU'] ||
    product.variant_sku ||
    product.sku ||
    product.SKU ||
    ''
  ).trim();

  const skuKeyIncoming = normalizeSKU(skuRawIncoming);

  console.log(`\n--- PRODUCT ${i + 1}: ${product.Title || 'Unknown'} ---`);
  console.log(`Incoming SKU_RAW="${skuRawIncoming}", SKU_KEY="${skuKeyIncoming}"`);

  // Always pass through, even if no SKU
  if (!skuKeyIncoming) {
    console.log(`⚠️  No usable SKU found after normalization - will create without SKU`);
    const result = {
      ...product,
      action: 'create',
      sku_raw: skuRawIncoming,
      sku_key: '',
      no_sku_warning: true
    };
    results.push({ json: result });
    continue;
  }

  const match = skuIndex.get(skuKeyIncoming);
  const duplicates = duplicateIndex.get(skuKeyIncoming) || [];
  const hasConflict = duplicates.length > 1;

  if (match) {
    // UPDATE path
    const conflictVariantIds = hasConflict ? duplicates.map(d => d.variant_id) : [];
    const result = {
      ...product,
      action: 'update',
      shopify_product_id: match.product_id,
      shopify_variant_id: match.variant_id,
      shopify_handle: match.handle,
      existing_product_title: match.product_title,
      existing_variant_title: match.variant_title,
      sku_raw: skuRawIncoming,
      sku_key: skuKeyIncoming,
      sku_conflict_warning: hasConflict || undefined,
      sku_conflict_variants: hasConflict ? conflictVariantIds : undefined
    };

    results.push({ json: result });
    console.log(`✅ UPDATE: Found existing variant ${match.variant_id} in product ${match.product_id}${hasConflict ? ' (DUPLICATE SKU KEY CONFLICT)' : ''}`);
  } else {
    // CREATE path
    const result = {
      ...product,
      action: 'create',
      sku_raw: skuRawIncoming,
      sku_key: skuKeyIncoming
    };
    results.push({ json: result });
    console.log(`✅ CREATE: SKU_KEY "${skuKeyIncoming}" not found in Shopify`);
  }
}

// 5) Summary
console.log(`\n=== FILTER RESULTS ===`);
console.log(`Total processed: ${results.length} products`);

const createCount = results.filter(r => r.json.action === 'create').length;
const updateCount = results.filter(r => r.json.action === 'update').length;
const noSkuCount  = results.filter(r => r.json.no_sku_warning).length;
const conflictCount = results.filter(r => r.json.sku_conflict_warning).length;

console.log(`- ${createCount} products to CREATE`);
console.log(`- ${updateCount} products to UPDATE`);
if (noSkuCount > 0)  console.log(`- ${noSkuCount} products without usable SKU`);
if (conflictCount > 0) console.log(`- ${conflictCount} UPDATEs flagged with DUPLICATE-SKU conflicts`);

results.forEach((r, index) => {
  const item = r.json;
  const action = item.action.toUpperCase();
  const skuInfo = item.sku_raw ? ` (SKU_RAW: ${item.sku_raw} | KEY: ${item.sku_key})` : ' (NO SKU)';
  const variantInfo = item.shopify_variant_id ? ` → variant: ${item.shopify_variant_id}` : '';
  const conflictInfo = item.sku_conflict_warning ? ` [DUPLICATE-SKU: ${item.sku_conflict_variants?.join(', ')}]` : '';
  console.log(`${index + 1}. ${item.Title || 'Untitled'}: ${action}${skuInfo}${variantInfo}${conflictInfo}`);
});

if (results.length === 0) {
  console.log(`⚠️  WARNING: No results to pass forward!`);
}

return results;

/******************************************************
 * CHECK & PACK PRICE UPDATES (single Code node)
 * - Match by normalized SKU
 * - Resolve duplicate SKUs by Product ID, then Handle, then Title similarity
 * - Update price; set compareAtPrice ONLY if empty and old>new
 * - Output only items needing update
 * - Emits both `graphql_body` (Admin GraphQL) and `rest_body` (REST) per item
 ******************************************************/

const CONFIG = {
  SHOPIFY_NODE: 'Shopify Get',      // GraphQL response node (must include price & compareAtPrice)
  SOURCE_NODE:  'Split images',     // Your Apify/normalized items node
  PRICE_DIFF_EPS: 0.009,            // ~1 cent tolerance
  ALLOW_TITLE_FALLBACK: true,       // last-resort resolver for duplicate SKUs
  TITLE_MATCH_MIN: 0.40,            // Jaccard threshold for title fallback
  DEBUG: false                      // true => emits one diagnostic when nothing to update
};

/* ==================== helpers ==================== */
const normalizeSKU = (raw) => raw == null ? '' : String(raw)
  .normalize('NFKC').replace(/[\u200B-\u200D\uFEFF]/g, '')
  .replace(/\s+/g, '').trim().toUpperCase();

const toNum = (v) => {
  if (v == null) return NaN;
  const s = String(v).replace(/\s/g, '').replace(',', '.');
  const m = s.match(/-?\d+(?:\.\d+)?/);
  return m ? Number(m[0]) : NaN;
};
const to2 = (n) => Number.isFinite(n) ? n.toFixed(2) : null;
const gidNum = (gid) => String(gid || '').split('/').pop();
const firstVal = (obj, keys) => { for (const k of keys) if (obj?.[k] != null && obj[k] !== '') return obj[k]; };

const tokenize = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g,' ')
  .trim().split(/\s+/).filter(Boolean);
const jaccard = (a, b) => {
  const A = new Set(tokenize(a)), B = new Set(tokenize(b));
  if (!A.size || !B.size) return 0;
  let inter = 0; for (const x of A) if (B.has(x)) inter++;
  const uni = A.size + B.size - inter;
  return inter / uni;
};
const parseHandleFromUrl = (url) => {
  const s = String(url || '');
  const m = s.match(/\/products\/([a-z0-9\-]+)/i);
  return m ? m[1] : '';
};

const readNode = (name) => { try { return $(name).all().map(x => x.json); } catch { return []; } };
const looksLikeShopify = (o) => !!(o?.data?.products?.edges || o?.products?.edges);

function getShopifyPayloads() {
  let items = readNode(CONFIG.SHOPIFY_NODE);
  if (!items.length) items = $input.all().map(x => x.json);
  const gql = items.filter(looksLikeShopify);
  return gql.length ? gql : [];
}

function getSourceItems() {
  let src = readNode(CONFIG.SOURCE_NODE);
  if (src.length) return src;
  const candidates = $input.all().map(x => x.json);
  return candidates.filter(o => o && (
    o['Variant SKU'] != null || o.variant_sku != null || o.sku != null || o.SKU != null
  ));
}

function readVariantPrices(v) {
  const p  = v?.price?.amount ?? v?.priceV2?.amount ?? v?.price;
  const cp = v?.compareAtPrice?.amount ?? v?.compareAtPriceV2?.amount ?? v?.compareAtPrice;
  return { price: toNum(p), compare: toNum(cp) };
}

function pickEntry(dups, prod) {
  // 1) product id
  const incomingIdRaw = firstVal(prod, ['Product ID','product_id','shopify_product_id','shopify_product_gid']);
  const incomingIdNum = incomingIdRaw ? gidNum(String(incomingIdRaw)) : '';
  if (incomingIdNum) {
    const byId = dups.find(d => d.product_id_num === incomingIdNum);
    if (byId) return byId;
  }
  // 2) handle (explicit or parsed from URL)
  const incomingHandle = (firstVal(prod, ['Handle','handle','Product Handle','shopify_handle']) || '') ||
                         parseHandleFromUrl(firstVal(prod, ['URL','Url','Link','Product URL','product_url']) || '');
  if (incomingHandle) {
    const byHandle = dups.find(d => d.handle === incomingHandle);
    if (byHandle) return byHandle;
  }
  // 3) title similarity
  if (CONFIG.ALLOW_TITLE_FALLBACK) {
    const srcTitle = firstVal(prod, ['Product Title','Title','title']) || '';
    let best = null, bestScore = -1;
    for (const d of dups) {
      const score = jaccard(srcTitle, d.product_title);
      if (score > bestScore) { best = d; bestScore = score; }
    }
    if (best && bestScore >= CONFIG.TITLE_MATCH_MIN) return best;
  }
  return null;
}

/* ==================== 1) Index Shopify variants ==================== */
const shopifyPayloads = getShopifyPayloads();
const skuGroups = new Map(); // skuKey -> [entries]
let indexed = 0;

for (const root of shopifyPayloads) {
  const edges = root?.data?.products?.edges ?? root?.products?.edges ?? [];
  for (const pe of edges) {
    const p = pe?.node; if (!p) continue;
    const handle = p.handle || '';
    const product_id_num = gidNum(p.id);

    const vEdges = p?.variants?.edges ?? [];
    for (const ve of vEdges) {
      const v = ve?.node; if (!v) continue;

      const skuKey = normalizeSKU(v.sku);
      if (!skuKey) continue;

      const { price, compare } = readVariantPrices(v);
      const entry = {
        variant_gid: String(v.id),
        variant_id_num: gidNum(v.id),
        product_id_num,
        handle,
        product_title: p.title || '',
        variant_title: v.title || '',
        existing_price: to2(price),            // strings or null
        existing_compare_at: to2(compare)
      };

      const arr = skuGroups.get(skuKey) || [];
      arr.push(entry);
      skuGroups.set(skuKey, arr);

      indexed++;
    }
  }
}

/* ==================== 2) Compare & emit only updates ==================== */
const incoming = getSourceItems();
const out = [];

let stats = {
  seen: incoming.length,
  noMatch: 0,
  noPrice: 0,
  duplicates: 0,
  unresolvedDup: 0,
  samePrice: 0,
  emitted: 0,
  resolvedById: 0,
  resolvedByHandle: 0,
  resolvedByTitle: 0
};

for (const prod of incoming) {
  const skuRaw = firstVal(prod, ['Variant SKU','variant_sku','sku','SKU']) || '';
  const skuKey = normalizeSKU(skuRaw);

  const incPrice = toNum(firstVal(prod, ['Variant Price','variant_price','price','Pret','pret']));
  if (!skuKey) continue;
  if (!Number.isFinite(incPrice)) { stats.noPrice++; continue; }

  const group = skuGroups.get(skuKey) || [];
  if (!group.length) { stats.noMatch++; continue; }

  let chosen = null;
  if (group.length === 1) {
    chosen = group[0];
  } else {
    stats.duplicates++;
    const picked = pickEntry(group, prod);
    if (!picked) { stats.unresolvedDup++; continue; }
    const incomingId = firstVal(prod, ['Product ID','product_id','shopify_product_id','shopify_product_gid']);
    const incomingHandle = (firstVal(prod, ['Handle','handle','Product Handle','shopify_handle']) || '') ||
                           parseHandleFromUrl(firstVal(prod, ['URL','Url','Link','Product URL','product_url']) || '');
    if (incomingId) stats.resolvedById++;
    else if (incomingHandle) stats.resolvedByHandle++;
    else stats.resolvedByTitle++;
    chosen = picked;
  }

  const existing = toNum(chosen.existing_price);
  const changed = Number.isFinite(existing) ? Math.abs(incPrice - existing) > CONFIG.PRICE_DIFF_EPS : true;
  if (!changed) { stats.samePrice++; continue; }

  const priceStr = to2(incPrice);

  // Respect existing compareAtPrice: only set if EMPTY and old>new
  const existingCompareNum = toNum(chosen.existing_compare_at);
  const hasCompareAt = Number.isFinite(existingCompareNum);
  const shouldSetCAP = (!hasCompareAt && Number.isFinite(existing) && existing > incPrice);
  const capStr = shouldSetCAP ? to2(existing) : undefined;

  // -------- Build payloads --------
  const graphql_body = {
    query: `mutation productVariantUpdate($input: ProductVariantInput!) {
      productVariantUpdate(input: $input) {
        productVariant { id price { amount currencyCode } compareAtPrice { amount currencyCode } }
        userErrors { field message }
      }
    }`,
    variables: {
      input: Object.assign(
        { id: chosen.variant_gid, price: priceStr },
        capStr ? { compareAtPrice: capStr } : {}
      )
    }
  };

  const rest_body = {
    variant: Object.assign(
      { id: Number(chosen.variant_id_num), price: priceStr },
      capStr ? { compare_at_price: capStr } : {}
    )
  };

  out.push({
    json: {
      action: 'update_price',
      sku_raw: String(skuRaw).trim(),
      sku_key: skuKey,
      product_title: chosen.product_title,
      variant_title: chosen.variant_title,
      shopify_handle: chosen.handle,
      shopify_product_id: chosen.product_id_num,
      variant_gid: chosen.variant_gid,             // for GraphQL
      variant_id: chosen.variant_id_num,           // for REST
      existing_price: chosen.existing_price,       // old Shopify price (string or null)
      existing_compare_at: chosen.existing_compare_at,
      incoming_price: priceStr,                    // new price
      old_price_used_as_compare_at: capStr || null,
      graphql_body,
      rest_body
    }
  });

  stats.emitted++;
}

/* ==================== 3) Diagnostics when nothing emitted ==================== */
if (!out.length && CONFIG.DEBUG) {
  return [{
    json: {
      diagnostic: {
        info: 'No items emitted; either prices are same, duplicates unresolved, or missing price/SKU.',
        counts: {
          shopify_variants_indexed: indexed,
          source_items_seen: stats.seen,
          duplicates_hit: stats.duplicates,
          unresolved_duplicates: stats.unresolvedDup,
          resolved_by_id: stats.resolvedById,
          resolved_by_handle: stats.resolvedByHandle,
          resolved_by_title: stats.resolvedByTitle,
          skipped_no_match: stats.noMatch,
          skipped_no_incoming_price: stats.noPrice,
          same_price: stats.samePrice,
          emitted_updates: stats.emitted
        },
        tips: [
          'Ensure Shopify Get query includes: handle, variants { id sku title price { amount } compareAtPrice { amount } }',
          'Send Product ID or Handle from source to break SKU ties deterministically.',
          'Only items needing update are forwarded by design.'
        ]
      }
    }
  }];
}

return out;

