// COMPLETE FILTER WITH DEDUPLICATION
// Handles: Deduplication from Split Images → CREATE/UPDATE/DEACTIVATE decisions
// All outputs are unique (no duplicate SKUs)

const gidNum = (gid) => String(gid || '').split('/').pop();

const normalizeSKU = (raw) => {
  if (raw == null) return '';
  return String(raw)
    .normalize('NFKC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\s+/g, '')
    .trim()
    .toUpperCase();
};

// ========== CONFIGURATION ==========
const INCLUDE_DEACTIVATIONS = true; // Set to false to skip deactivation outputs
const EXCLUDE_IMAGE_FIELDS = true; // Remove image fields from output

const IMAGE_FIELDS_TO_EXCLUDE = [
  'image', 'images', 'Image', 'Images',
  'product_image', 'variant_image',
  'featuredImage', 'featured_image',
  'image_url', 'imageUrl', 'image_src',
  'Variant Image', 'Product Image'
];
// ===================================

// Helper to remove image fields
const removeImageFields = (obj) => {
  if (!EXCLUDE_IMAGE_FIELDS) return obj;
  const cleaned = { ...obj };
  IMAGE_FIELDS_TO_EXCLUDE.forEach(field => {
    delete cleaned[field];
  });
  return cleaned;
};

console.log("=== COMPLETE FILTER WITH DEDUPLICATION ===");
console.log(`Configuration:`);
console.log(`- Include Deactivations: ${INCLUDE_DEACTIVATIONS}`);
console.log(`- Exclude Image Fields: ${EXCLUDE_IMAGE_FIELDS}`);
console.log("");

// ============================================
// STEP 1: Build Shopify SKU index (unique)
// ============================================
const shopifyResults = $input.all().map(i => i.json);
const uniqueShopifySkus = new Map(); // Key: normalized SKU → Value: data
let totalShopifyProducts = 0;
let totalShopifyVariants = 0;

console.log("📦 PROCESSING SHOPIFY DATA...");

for (const result of shopifyResults) {
  const productsData = result?.data?.products;
  if (!productsData) continue;

  const productEdges = productsData.edges ?? [];
  totalShopifyProducts += productEdges.length;

  for (const productEdge of productEdges) {
    const product = productEdge.node;
    if (!product) continue;

    const productId = gidNum(product.id);
    const productTitle = product.title || '';
    const vendor = product.vendor || '';
    const handle = product.handle || '';

    const variantEdges = product.variants?.edges ?? [];
    totalShopifyVariants += variantEdges.length;

    for (const variantEdge of variantEdges) {
      const variant = variantEdge.node;
      if (!variant) continue;

      const variantId = gidNum(variant.id);
      const skuRaw = variant.sku ? String(variant.sku).trim() : '';
      const skuKey = normalizeSKU(skuRaw);

      if (!skuKey || !variantId) continue;

      // Store only first occurrence of each SKU
      if (!uniqueShopifySkus.has(skuKey)) {
        uniqueShopifySkus.set(skuKey, {
          product_id: productId,
          variant_id: variantId,
          handle,
          product_title: productTitle,
          variant_title: variant.title || 'Default Title',
          vendor,
          sku_raw: skuRaw,
          sku_key: skuKey,
          price: variant.price || '',
          inventory_quantity: variant.inventoryQuantity || 0
        });
      }
    }
  }
}

console.log(`  Shopify Products: ${totalShopifyProducts}`);
console.log(`  Shopify Variants: ${totalShopifyVariants}`);
console.log(`  Unique Shopify SKUs: ${uniqueShopifySkus.size}`);

// ============================================
// STEP 2: DEDUPLICATE Split Images data
// ============================================
console.log("\n📥 PROCESSING SPLIT IMAGES DATA...");

let incomingProductsRaw = [];
const uniqueIncomingProducts = new Map(); // Key: normalized SKU → Value: product data
const incomingSKUKeys = new Set(); // Track all unique incoming SKUs
let duplicatesFromImages = 0;

try {
  const splitImagesItems = $('Split images').all();
  incomingProductsRaw = splitImagesItems.map(item => item.json);
  console.log(`  Raw records (with duplicates): ${incomingProductsRaw.length}`);
} catch (error) {
  console.log(`⚠️ Could not access Split Images data: ${error.message}`);
  return [{
    json: {
      error: "Cannot access Split images data",
      shopify_skus: uniqueShopifySkus.size
    }
  }];
}

// Deduplicate incoming products (keep first occurrence of each SKU)
for (const product of incomingProductsRaw) {
  const skuRaw = String(
    product['Variant SKU'] ||
    product.variant_sku ||
    product.sku ||
    product.SKU ||
    ''
  ).trim();

  const skuKey = normalizeSKU(skuRaw);

  // For products without SKU, we'll use a unique identifier to avoid losing them
  const uniqueKey = skuKey || `no_sku_${Math.random().toString(36).substr(2, 9)}`;

  if (skuKey && uniqueIncomingProducts.has(skuKey)) {
    duplicatesFromImages++;
  } else {
    // Store the first occurrence
    uniqueIncomingProducts.set(uniqueKey, {
      ...removeImageFields(product),
      sku_raw: skuRaw,
      sku_key: skuKey
    });

    if (skuKey) {
      incomingSKUKeys.add(skuKey);
    }
  }
}

console.log(`  Duplicates removed: ${duplicatesFromImages}`);
console.log(`  Unique products after dedup: ${uniqueIncomingProducts.size}`);
console.log(`  Unique SKUs with values: ${incomingSKUKeys.size}`);

// ============================================
// STEP 3: Process CREATE/UPDATE actions
// ============================================
console.log("\n🔄 DETERMINING ACTIONS...");

const results = [];
let createCount = 0;
let updateCount = 0;
let noSkuCount = 0;

// Process each unique incoming product
for (const [uniqueKey, product] of uniqueIncomingProducts.entries()) {
  const skuKey = product.sku_key;

  if (!skuKey) {
    // No SKU - create without SKU
    results.push({
      json: {
        ...product,
        action: 'create',
        no_sku_warning: true
      }
    });
    createCount++;
    noSkuCount++;
    continue;
  }

  const match = uniqueShopifySkus.get(skuKey);

  if (match) {
    // UPDATE - SKU exists in Shopify
    results.push({
      json: {
        ...product,
        action: 'update',
        shopify_product_id: match.product_id,
        shopify_variant_id: match.variant_id,
        shopify_handle: match.handle,
        existing_product_title: match.product_title,
        existing_variant_title: match.variant_title
      }
    });
    updateCount++;
  } else {
    // CREATE - SKU doesn't exist in Shopify
    results.push({
      json: {
        ...product,
        action: 'create'
      }
    });
    createCount++;
  }
}

// ============================================
// STEP 4: Process DEACTIVATE actions
// ============================================
let deactivateCount = 0;

if (INCLUDE_DEACTIVATIONS) {
  console.log("\n🔍 FINDING DEACTIVATIONS...");

  for (const [skuKey, shopifyData] of uniqueShopifySkus.entries()) {
    if (!incomingSKUKeys.has(skuKey)) {
      // This SKU exists in Shopify but NOT in incoming data
      results.push({
        json: {
          action: 'deactivate',
          shopify_product_id: shopifyData.product_id,
          shopify_variant_id: shopifyData.variant_id,
          shopify_handle: shopifyData.handle,
          existing_product_title: shopifyData.product_title,
          existing_variant_title: shopifyData.variant_title,
          existing_vendor: shopifyData.vendor,
          existing_price: shopifyData.price,
          existing_inventory: shopifyData.inventory_quantity,
          sku_raw: shopifyData.sku_raw,
          sku_key: shopifyData.sku_key,
          reason: 'SKU not found in Split Images'
        }
      });
      deactivateCount++;
    }
  }
}

// ============================================
// STEP 5: Summary
// ============================================
console.log("\n===============================================");
console.log("📊 FINAL RESULTS SUMMARY");
console.log("===============================================");
console.log("INPUT:");
console.log(`  Split Images: ${incomingProductsRaw.length} raw → ${uniqueIncomingProducts.size} unique`);
console.log(`  Shopify: ${totalShopifyVariants} variants → ${uniqueShopifySkus.size} unique SKUs`);
console.log("\nOUTPUT: " + results.length + " total records");
console.log(`  ✅ CREATE: ${createCount} (${noSkuCount} without SKU)`);
console.log(`  🔄 UPDATE: ${updateCount}`);
if (INCLUDE_DEACTIVATIONS) {
  console.log(`  🔴 DEACTIVATE: ${deactivateCount}`);
}
console.log("===============================================");

// ============================================
// STEP 6: Verify uniqueness
// ============================================
const skuVerification = new Map();
let duplicateActions = 0;

results.forEach(item => {
  const sku = item.json.sku_raw || item.json.sku_key;
  if (sku) {
    const action = item.json.action;
    const key = `${sku}_${action}`;
    if (skuVerification.has(key)) {
      duplicateActions++;
      console.log(`⚠️ Duplicate found: SKU "${sku}" with action "${action}"`);
    }
    skuVerification.set(key, true);
  }
});

console.log(`\n✅ Uniqueness Check: ${duplicateActions === 0 ? 'PASSED - All records unique' : `FAILED - ${duplicateActions} duplicates found`}`);

// Show sample outputs
if (results.length > 0) {
  console.log("\n📋 Sample outputs (first 5):");
  results.slice(0, 5).forEach((item, idx) => {
    const d = item.json;
    const title = d.Title || d.existing_product_title || 'Unknown';
    console.log(`${idx + 1}. ${d.action.toUpperCase()}: ${title} (SKU: ${d.sku_raw || 'none'})`);
  });

  if (results.length > 5) {
    console.log(`... and ${results.length - 5} more records`);
  }
}

return results;

