// Handles duplicate SKUs from Split Images (multiple images per product)
// Outputs ONLY unique SKUs that need deactivation

const gidNum = (gid) => String(gid || '').split('/').pop();

const normalizeSKU = (raw) => {
  if (raw == null) return '';
  return String(raw)
    .normalize('NFKC')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/\s+/g, '')
    .trim()
    .toUpperCase();
};

console.log("=== DEDUPLICATION & DEACTIVATION FILTER ===");
console.log("Handling duplicate SKUs from image splitting...\n");

// 1) Collect and DEDUPLICATE Shopify SKUs
const shopifyResults = $input.all().map(i => i.json);
const uniqueShopifySkus = new Map(); // Key: normalized SKU → Value: first occurrence data
let totalShopifyRecords = 0;

for (const result of shopifyResults) {
  const productsData = result?.data?.products;
  if (!productsData) continue;

  const productEdges = productsData.edges ?? [];

  for (const productEdge of productEdges) {
    const product = productEdge.node;
    if (!product) continue;

    const productId = gidNum(product.id);
    const productTitle = product.title || '';
    const vendor = product.vendor || '';
    const handle = product.handle || '';

    const variantEdges = product.variants?.edges ?? [];

    for (const variantEdge of variantEdges) {
      const variant = variantEdge.node;
      if (!variant) continue;

      totalShopifyRecords++;

      const variantId = gidNum(variant.id);
      const skuRaw = variant.sku ? String(variant.sku).trim() : '';
      const skuKey = normalizeSKU(skuRaw);

      // Skip empty SKUs
      if (!skuKey || !variantId) continue;

      // Keep only FIRST occurrence of each unique SKU
      if (!uniqueShopifySkus.has(skuKey)) {
        uniqueShopifySkus.set(skuKey, {
          sku: skuRaw,
          product_id: productId,
          variant_id: variantId,
          product_title: productTitle,
          variant_title: variant.title || 'Default Title',
          vendor: vendor || '',
          price: variant.price || '0',
          inventory: variant.inventoryQuantity || 0,
          handle: handle
        });
      }
    }
  }
}

console.log(`📊 SHOPIFY DATA:`);
console.log(`  Total records processed: ${totalShopifyRecords}`);
console.log(`  Unique SKUs found: ${uniqueShopifySkus.size}`);

// 2) Collect and DEDUPLICATE incoming SKUs from Split Images
// This is where we handle the duplication from multiple images per product
const incomingSkus = new Set();
const incomingFirstOccurrence = new Map(); // Track first occurrence of each SKU
let totalIncomingRecords = 0;
let duplicatesFromImages = 0;

try {
  const splitImagesItems = $('Split images').all();
  const incomingProducts = splitImagesItems.map(item => item.json);
  totalIncomingRecords = incomingProducts.length;

  console.log(`\n📥 SPLIT IMAGES DATA:`);
  console.log(`  Total records (including duplicates from images): ${totalIncomingRecords}`);

  for (const product of incomingProducts) {
    const skuRaw = String(
      product['Variant SKU'] ||
      product.variant_sku ||
      product.sku ||
      product.SKU ||
      ''
    ).trim();

    const skuKey = normalizeSKU(skuRaw);
    if (skuKey) {
      if (incomingSkus.has(skuKey)) {
        duplicatesFromImages++;
      } else {
        // Store first occurrence data if needed
        incomingFirstOccurrence.set(skuKey, {
          title: product.Title || product.title || '',
          sku: skuRaw
        });
      }
      incomingSkus.add(skuKey);
    }
  }

  console.log(`  Duplicates from multiple images: ${duplicatesFromImages}`);
  console.log(`  Unique SKUs after deduplication: ${incomingSkus.size}`);

} catch (error) {
  console.log(`⚠️ Error accessing Split Images: ${error.message}`);
  return [{
    json: {
