console.log(`  Split Images: ${totalIncomingRecords} records → ${incomingSkus.size} unique SKUs`);
console.log(`  Reduction: ${totalIncomingRecords - incomingSkus.size} duplicate records removed`);
console.log(`\nCOMPARISON:`);
