console.log(`  UNIQUE SKUs to deactivate: ${deactivateList.length}`);
console.log(`  (These exist in Shopify but NOT in Split Images)`);
console.log("===============================================");

// 5) Show sample
if (deactivateList.length > 0) {
  console.log("\n📋 First 3 SKUs to deactivate:");
  const sample = deactivateList.slice(0, 3);

  sample.forEach((item, idx) => {
    const d = item.json;
    console.log(`\n${idx + 1}. SKU: "${d.sku}"`);
    console.log(`   Product: ${d.product_title}`);
    console.log(`   IDs: Product=${d.product_id}, Variant=${d.variant_id}`);
  });

  if (deactivateList.length > 3) {
    console.log(`\n... plus ${deactivateList.length - 3} more unique SKUs`);
  }
}

// 6) Final verification of uniqueness
const finalCheck = new Set();
let outputDuplicates = 0;

deactivateList.forEach(item => {
  if (finalCheck.has(item.json.sku)) {
    outputDuplicates++;
  }
  finalCheck.add(item.json.sku);
});

console.log(`\n✅ UNIQUENESS VERIFICATION:`);
console.log(`  Output contains ${deactivateList.length} records`);
console.log(`  All SKUs are unique: ${outputDuplicates === 0 ? 'YES ✓' : 'NO ✗'}`);

if (outputDuplicates > 0) {
  console.log(`  ⚠️ WARNING: ${outputDuplicates} duplicates detected!`);
}

return deactivateList;
